"use client"

import * as React from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { ArrowUpRightIcon, GlobeIcon, XIcon } from "lucide-react"

import { LivepeerGradientSymbol, LivepeerWordmark } from "@/components/brand"
import {
  DiscordIcon,
  GitHubIcon,
  XIcon as SocialXIcon,
} from "@/components/brand-social-icons"
import { Button } from "@/components/ui/button"
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet"
import { cn } from "@/lib/utils"
import type { LivepeerOrgSite } from "@/components/mockups/contracts"

const socialIcons = {
  discord: DiscordIcon,
  x: SocialXIcon,
  github: GitHubIcon,
  website: GlobeIcon,
}

function LivepeerMenuIcon() {
  return (
    <svg
      viewBox="0 0 32 16"
      fill="currentColor"
      aria-hidden="true"
      className="size-4 w-8"
    >
      <path d="M1 2h30v4H1zM9 10h22v4H9z" />
    </svg>
  )
}

export function LivepeerOrgMenu({ site }: { site: LivepeerOrgSite }) {
  const pathname = usePathname()
  const [open, setOpen] = React.useState(false)

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        render={
          <Button
            variant="ghost"
            size="icon-sm"
            className="hover:bg-transparent hover:text-emerald-500"
          />
        }
      >
        <LivepeerMenuIcon />
        <span className="sr-only">Open site navigation</span>
      </SheetTrigger>
      <SheetContent
        side="top"
        showCloseButton={false}
        overlayClassName="bg-transparent transition-none supports-backdrop-filter:backdrop-blur-none"
        className="h-dvh max-h-none overflow-y-auto border-0 bg-foreground text-background shadow-none duration-200 ease-out data-ending-style:opacity-100 data-ending-style:duration-150 data-ending-style:ease-in data-starting-style:opacity-100 data-[side=top]:border-b-0 motion-reduce:transition-none sm:h-auto sm:max-h-dvh"
      >
        <header className="flex h-16 items-center justify-between px-4 sm:px-6 lg:px-10">
          <SheetTitle className="text-left">
            <span
              className="flex items-center gap-1.5 text-background"
              aria-label="Livepeer"
            >
              <LivepeerGradientSymbol className="h-3.5 w-auto sm:h-4" />
              <LivepeerWordmark className="h-3.5 w-auto sm:h-4" />
            </span>
          </SheetTitle>
          <SheetClose
            render={
              <Button
                variant="ghost"
                size="icon-sm"
                className="text-background hover:bg-transparent hover:text-emerald-500"
              />
            }
          >
            <XIcon />
            <span className="sr-only">Close site navigation</span>
          </SheetClose>
        </header>

        <div className="grid gap-12 px-4 pt-10 pb-8 sm:gap-16 sm:px-6 sm:pt-14 lg:px-10">
          <nav className="flex flex-col items-start gap-4 text-left">
            {site.menuLinks.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setOpen(false)}
                className={cn(
                  "text-2xl font-light tracking-tight transition-colors hover:text-emerald-500 sm:text-3xl",
                  pathname === item.href
                    ? "text-background underline underline-offset-8"
                    : "text-background/55"
                )}
              >
                {item.label}
              </Link>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            {site.socialLinks.map((social) => {
              const Icon = socialIcons[social.service]

              return (
                <a
                  key={social.label}
                  href={social.href}
                  target="_blank"
                  rel="noreferrer"
                  aria-label={social.label}
                  className="text-background/55 transition-colors hover:text-emerald-500"
                >
                  <Icon className="size-5" aria-hidden="true" />
                </a>
              )
            })}
          </div>

          <div className="grid gap-10 sm:grid-cols-3">
            {site.footerGroups.map((group) => (
              <div key={group.title}>
                <h2 className="text-sm font-medium text-background">
                  {group.title}
                </h2>
                <div className="mt-4 flex flex-col items-start gap-3">
                  {group.links.map((link) => {
                    const external = link.href.startsWith("http")

                    return (
                      <a
                        key={link.label}
                        href={link.href}
                        target={external ? "_blank" : undefined}
                        rel={external ? "noreferrer" : undefined}
                        onClick={() => setOpen(false)}
                        className="inline-flex items-center gap-1 text-sm text-background/55 transition-colors hover:text-emerald-500"
                      >
                        {link.label}
                        {external && (
                          <ArrowUpRightIcon
                            className="size-3.5"
                            aria-hidden="true"
                          />
                        )}
                      </a>
                    )
                  })}
                </div>
              </div>
            ))}
          </div>

          <p className="text-xs text-background/55">{site.copyright}</p>
        </div>
      </SheetContent>
    </Sheet>
  )
}

export type AgentConsoleLink = { _key?: string; label: string; href: string }

export interface AgentConsoleShell {
  _id: string
  homeAriaLabel: string
  navigation: (AgentConsoleLink & { external: boolean })[]
  userMenu: {
    accountLabel: string
    manageProfileLabel: string
    developerDocsLabel: string
    termsLabel: string
    helpLabel: string
    logoutLabel: string
  }
  auth: {
    dialogLabel: string
    title: string
    description: string
    googleLabel: string
    discordLabel: string
    emailDividerLabel: string
    emailInputLabel: string
    emailPlaceholder: string
    continueLabel: string
  }
}

export interface AgentConsoleUser {
  username: string
  email: string
}

export type VideoBuddyPageName =
  | "home"
  | "characters"
  | "footage"
  | "install"
  | "projects"
  | "protocol"
  | "storyboards"

export type VideoBuddyProtocolIcon = "play" | "blocks" | "cpu"

export interface VideoBuddyPageContent {
  _id: string
  _type: "videoBuddyPageContent"
  page: VideoBuddyPageName
  metadataTitle: string
  heading?: string
  description?: string
  primaryActionLabel?: string
  emptyStateTitle?: string
  supportingText?: string
  protocol?: {
    eyebrow: string
    flowHeading: string
    layers: {
      _key: string
      number: string
      title: string
      description: string
      detail: string
      href: string
      icon: VideoBuddyProtocolIcon
    }[]
    requestHeading: string
    requestSteps: { _key: string; title: string; description: string }[]
    agentPropertyHeading: string
    agentPropertyDescription: string
    paymentPropertyHeading: string
    paymentPropertyDescription: string
    architectureLinkLabel: string
    architectureLinkHref: string
  }
}

export type EditorialLink = { _key?: string; label: string; href: string }
export type LivepeerOrgPageSlug =
  | "home"
  | "livepeer-agent"
  | "playbook-library"
  | "ecosystem"
  | "provide-gpu-compute"

export interface LivepeerOrgSite {
  _id: "livepeerOrgSite"
  homeHref: string
  menuLinks: EditorialLink[]
  footerTagline: string
  footerGroups: { _key: string; title: string; links: EditorialLink[] }[]
  socialLinks: (EditorialLink & {
    service: "discord" | "x" | "github" | "website"
  })[]
  copyright: string
}

export interface EcosystemEditorialApp {
  _key: string
  name: string
  domain: string
  href: string
  description: string
  image: string
  tags: string[]
}

export interface LivepeerOrgPage {
  _id: string
  page: LivepeerOrgPageSlug
  seoTitle: string
  seoDescription?: string
  homeContent?: {
    hero: {
      heading: string
      accent: string
      primaryCta: EditorialLink
      secondaryCta: EditorialLink
    }
    agentFeature: {
      description: string
      installCta: EditorialLink
      libraryCta: EditorialLink
    }
    providerCta: { heading: string; description: string; cta: EditorialLink }
  }
  agentContent?: {
    hero: {
      heading: string
      description: string
      serverUrl: string
      signInCta: EditorialLink
      createAccountCta: EditorialLink
    }
    access: { heading: string; description: string; cta: EditorialLink }
    capabilities: { heading: string; cta: EditorialLink }
    playbooks: { heading: string; description: string; cta: EditorialLink }
  }
  libraryContent?: {
    heading: string
    description: string
    searchPlaceholder: string
    allCategoryLabel: string
    emptyMessage: string
    footerHeading: string
  }
  ecosystemContent?: {
    heading: string
    description: string
    submitLabel: string
    searchPlaceholder: string
    emptyMessage: string
    apps: EcosystemEditorialApp[]
    submission: {
      heading: string
      description: string
      steps: { _key: string; heading: string; description: string }[]
      templatePath: string
      template: string
      closeLabel: string
      githubCta: EditorialLink
    }
  }
  earnContent?: {
    earnings: {
      servicePayoutsLabel: string
      protocolRewardsLabel: string
      periodLabel: string
    }
    hero: { heading: string; description: string; cta: EditorialLink }
    pathsHeading: string
    pathsDescription: string
    paths: {
      _key: string
      heading: string
      fit: string
      description: string
      icon: "cable" | "sparkles" | "server-cog"
      requirements: string[]
      note: string
      cta: EditorialLink
    }[]
    baselineHeading: string
    baselineDescription: string
    baseline: {
      _key: string
      heading: string
      description: string
      icon: "cpu" | "server" | "network" | "dollar"
    }[]
    arbitrum: {
      heading: string
      description: string
      imageAlt: string
      disclaimer: string
      cta: EditorialLink
    }
    stake: { heading: string; description: string; cta: EditorialLink }
  }
}

export interface WaitlistPageContent {
  _id: string
  metadata: { title: string; description: string }
  backgroundHero: { brandAriaLabel: string; agentLabel: string }
  panel: {
    brandAriaLabel: string
    agentLabel: string
    heading: string
    description: string
    joinedToast: string
    referralPrompt: string
  }
  signupForm: {
    label: string
    emailPlaceholder: string
    submitAriaLabel: string
  }
  statusCard: { positionLabel: string; referralsLabel: string }
  referralLink: { copyAriaLabel: string; copiedToast: string }
  leaderboard: {
    heading: string
    personColumnLabel: string
    referralsColumnLabel: string
    currentUserLabel: string
  }
}

