        <linearGradient id={gradientId} x1="0" y1="0" x2=".342" y2="1">
          <stop offset="0" stopColor="color(display-p3 0.04 0.74 0.49)" />
          <stop offset=".32" stopColor="color(display-p3 0.04 0.74 0.49)" />
